      margin: 0 0 2rem;
      color: var(--color-muted);
    }

    .required-note {
      margin: 0 0 1.25rem;
      color: var(--color-muted);
      font-size: 0.95rem;
    }

    .required-marker {
      color: var(--color-error);
      font-weight: 800;
    }

    .form-field {
      margin-bottom: 1.25rem;
