<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <header class="page-header">
    <a class="brand" href="#" aria-label="Acme Support home">
      <span class="brand-mark" aria-hidden="true">A</span>
      Acme Support
    </a>
  </header>

  <main id="main-content">
    <section class="support-card" aria-labelledby="page-title">
      <div class="support-copy">
        <p class="eyebrow">Support team</p>
        <h1 id="page-title">How can we help?</h1>
        <p class="intro">
          Tell us how to reach you and our support team will follow up with practical next steps.
        </p>
        <p class="contact-note">
          We usually respond within one business day. Required fields are marked with an asterisk.
        </p>
      </div>

      <div class="form-panel">
        <h2 class="form-heading">Contact details</h2>
        <p class="form-description">Share your preferred contact information so we can route your request.</p>
        <p class="required-note"><span class="required-marker">*</span> Required field</p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">
              Full name <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
              aria-invalid="false"
            >
            <p class="error-message" id="full-name-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="email">
              Email address <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-describedby="email-error"
              aria-invalid="false"
            >
            <p class="error-message" id="email-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="phone">
              Phone number <span class="optional-label">(optional)</span>
            </label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-helper phone-error"
              aria-invalid="false"
            >
            <p class="helper-text" id="phone-helper">Use 10 digits, such as 555-123-4567.</p>
            <p class="error-message" id="phone-error" aria-live="polite"></p>
          </div>

          <button class="submit-button" type="submit">Submit support request</button>
          <p class="status-message" id="form-status" aria-live="polite"></p>
        </form>
      </div>
    </section>
  </main>

  <footer class="page-footer">
    <p>&copy; 2026 Acme Support. We are here to help.</p>
  </footer>

  <script>
    const form = document.querySelector("#support-form");
    const statusMessage = document.querySelector("#form-status");
    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Enter your full name.";
          }

          if (value.trim().length < 2) {
            return "Full name must be at least 2 characters.";
          }

          return "";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          const trimmedValue = value.trim();
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!trimmedValue) {
            return "Enter your email address.";
          }

          if (!emailPattern.test(trimmedValue)) {
            return "Enter a valid email address, such as name@example.com.";
          }

          return "";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const trimmedValue = value.trim();
          const phonePattern = /^(\+1[\s.-]?)?(\(?\d{3}\)?[\s.-]?)\d{3}[\s.-]?\d{4}$/;

          if (trimmedValue && !phonePattern.test(trimmedValue)) {
            return "Enter a phone number in the format 555-123-4567.";
          }

          return "";
        }
      }
    };

    function showError(field, message) {
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
      field.error.textContent = message;
      field.error.classList.toggle("is-visible", Boolean(message));
    }

    function validateField(field) {
      const errorMessage = field.validate(field.input.value);
      showError(field, errorMessage);
      return !errorMessage;
    }

    function validateForm() {
      return Object.values(fields).reduce((isValid, field) => {
        return validateField(field) && isValid;
      }, true);
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("blur", () => {
        validateField(field);
      });

      field.input.addEventListener("input", () => {
        if (field.input.getAttribute("aria-invalid") === "true") {
          validateField(field);
        }

        statusMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      statusMessage.textContent = "";

      if (!validateForm()) {
        const firstInvalidInput = form.querySelector('[aria-invalid="true"]');
        firstInvalidInput.focus();
        return;
      }

      form.reset();
      Object.values(fields).forEach((field) => showError(field, ""));
      statusMessage.textContent = "Thanks. Your support request contact details have been submitted.";
    });
