+        <p class="form-description">Share your preferred contact information so we can route your request.</p>
+        <p class="required-note"><span class="required-marker">*</span> Required field</p>
+
+        <form id="support-form" novalidate>
+          <div class="form-field">
+            <label for="full-name">
+              Full name <span class="required-marker" aria-hidden="true">*</span>
+            </label>
+            <input
+              id="full-name"
+              name="fullName"
+              type="text"
+              autocomplete="name"
+              required
+              aria-describedby="full-name-error"
+              aria-invalid="false"
+            >
+            <p class="error-message" id="full-name-error" aria-live="polite"></p>
+          </div>
+
+          <div class="form-field">
+            <label for="email">
+              Email address <span class="required-marker" aria-hidden="true">*</span>
+            </label>
+            <input
+              id="email"
+              name="email"
+              type="email"
+              autocomplete="email"
+              inputmode="email"
+              required
+              aria-describedby="email-error"
+              aria-invalid="false"
+            >
+            <p class="error-message" id="email-error" aria-live="polite"></p>
+          </div>
+
