+            <label for="phone">
+              Phone number <span class="optional-label">(optional)</span>
+            </label>
+            <input
+              id="phone"
+              name="phone"
+              type="tel"
+              autocomplete="tel"
+              inputmode="tel"
+              aria-describedby="phone-helper phone-error"
+              aria-invalid="false"
+            >
+            <p class="helper-text" id="phone-helper">Use 10 digits, such as 555-123-4567.</p>
+            <p class="error-message" id="phone-error" aria-live="polite"></p>
+          </div>
+
